using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class ReportGeometryPick {public static string Main(){var camera=new GameObject("Temporary geometry pick",typeof(Camera)).GetComponent<Camera>();camera.CopyFrom(Camera.main);camera.enabled=false;camera.aspect=1280f/720;var p=new Vector3(984.09f,132.66f,-67.39f);var f=Quaternion.Euler(0,241.87f,0)*Vector3.forward;camera.transform.SetPositionAndRotation(p-f*6+Vector3.up*3.5f,Quaternion.LookRotation(f*25-Vector3.up*3));var intersect=typeof(HandleUtility).GetMethod("IntersectRayMesh",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public);var rows=new List<string>();foreach(var uv in new[]{new Vector2(.82f,.64f),new Vector2(.91f,.48f),new Vector2(.56f,.64f),new Vector2(.30f,.60f)}){var ray=camera.ViewportPointToRay(uv);var hits=new List<(float d,string name)>();foreach(var mf in Object.FindObjectsByType<MeshFilter>()){var r=mf.GetComponent<Renderer>();if(!r||!r.enabled||!mf.sharedMesh||!r.bounds.IntersectRay(ray))continue;object[] args={ray,mf.sharedMesh,mf.transform.localToWorldMatrix,new RaycastHit()};if((bool)intersect.Invoke(null,args)){var hit=(RaycastHit)args[3];hits.Add((hit.distance,mf.name+" @"+hit.point+" "+AssetDatabase.GetAssetPath(mf.sharedMesh)));}}rows.Add(uv+"\n"+string.Join("\n",hits.OrderBy(h=>h.d).Take(4).Select(h=>h.name)));}Object.DestroyImmediate(camera.gameObject);File.WriteAllLines("Docs/ReportCleanup/visual-mesh-picks.txt",rows);return string.Join("\n",rows);}}
